ULTIMATE = 1386  # start.gg videogame id of Super Smash Bros. Ultimate
# Sets per request. A set costs about 33 objects on average against the 1000-object limit,
# but best-of-5 sets cost far more: for Sparg0, 25 and even 20 per page went over on some page
# (probe, Nov 2026). 15 never did. player_sets starts over with a smaller page if one does.
PER_PAGE = 15
# Sets per request with queries.USAGE_SETS (about 27 objects a set): 30 came to 790-809 objects
# for Sparg0 / rm8, 40 went over (Nov 2026).
USAGE_PER_PAGE = 30
# start.gg's names that don't match char.parquet's by name (a word more or less), by char_id
# (spec/pkgs/ds/data/external_sources.md). Found by `ds data startgg-char`, Nov 2026.
SITE_CHARACTER = {"rosalina_and_luma": "Rosalina", "simon": "Simon Belmont"}
_CHAR_ID_BY_SITE_NAME = {name: char_id for char_id, name in SITE_CHARACTER.items()}
_SET_COMPLETED = 3
_EVENT_SLUG_RE = re.compile(r"(tournament/[^/?#]+/event/[^/?#]+)")
_USER_SLUG_RE = re.compile(r"(?:^|/)user/([0-9a-zA-Z]+)")


def _time(timestamp: int | None) -> dt.datetime | None:
    return dt.datetime.fromtimestamp(timestamp, dt.UTC) if timestamp else None


def _player(node: dict[str, Any], user_slug_: str | None = None) -> Player:
    slug = user_slug_ or (node.get("user") or {}).get("slug")
    return Player(id=node["id"], tag=node.get("gamerTag") or "", prefix=node.get("prefix") or None, user_slug=slug)


def _tournament(node: dict[str, Any]) -> Tournament:
    return Tournament(
        id=node["id"],
        name=node.get("name") or "",
        slug=node.get("slug") or "",
        start_at=_time(node.get("startAt")),
        end_at=_time(node.get("endAt")),
        city=node.get("city"),
        state=node.get("addrState"),
        country=node.get("countryCode"),
        venue=node.get("venueName"),
        online=node.get("isOnline"),
        num_attendees=node.get("numAttendees"),
        events=[_event(e) for e in node.get("events") or []],
    )


def _event(node: dict[str, Any]) -> Event:
    return Event(
        id=node["id"],
        name=node.get("name") or "",
        slug=node.get("slug") or "",
        start_at=_time(node.get("startAt")),
        online=node.get("isOnline"),
        num_entrants=node.get("numEntrants"),
        videogame_id=(node.get("videogame") or {}).get("id"),
        tournament=_tournament(node["tournament"]) if node.get("tournament") else None,
    )


def _players(entrant: dict[str, Any]) -> list[Player]:
    return [_player(p["player"]) for p in entrant.get("participants") or [] if p.get("player")]


def _entrant(node: dict[str, Any], placement: int | None = None) -> Entrant:
    return Entrant(
        id=node["id"],
        name=node.get("name"),
        players=_players(node),
        seed=node.get("initialSeedNum"),
        disqualified=node.get("isDisqualified"),
        placement=placement if placement is not None else (node.get("standing") or {}).get("placement"),
    )


def _side(slot: dict[str, Any]) -> SetSide:
    entrant = slot.get("entrant") or {}
    standing = slot.get("standing") or {}
    score = ((standing.get("stats") or {}).get("score") or {}).get("value")
    return SetSide(
        entrant_id=entrant.get("id"),
        name=entrant.get("name"),
        players=_players(entrant),
        seed=entrant.get("initialSeedNum"),
        disqualified=entrant.get("isDisqualified"),
        score=score,
        placement=standing.get("placement"),
    )


def _game(node: dict[str, Any], characters: dict[int, Character]) -> Game:
    selections = [
        Selection(
            entrant_id=s["entrant"]["id"],
            character=characters.get(s["selectionValue"])
            or Character(id=s["selectionValue"], name=f"character {s['selectionValue']}"),
        )
        for s in node.get("selections") or []
        if s.get("selectionType") == "CHARACTER" and s.get("entrant") and s.get("selectionValue") is not None
    ]
    return Game(
        number=node.get("orderNum") or 0,
        winner_entrant_id=node.get("winnerId"),
        stage=Stage(id=node["stage"]["id"], name=node["stage"].get("name") or "") if node.get("stage") else None,
        selections=selections,
        entrant1_score=node.get("entrant1Score"),
        entrant2_score=node.get("entrant2Score"),
    )


def _set(node: dict[str, Any], characters: dict[int, Character]) -> Set:
    games = sorted((_game(g, characters) for g in node.get("games") or []), key=lambda g: g.number)
    return Set(
        id=str(node["id"]),
        completed_at=_time(node.get("completedAt")),
        round_text=node.get("fullRoundText"),
        round=node.get("round"),
        total_games=node.get("totalGames"),
        winner_entrant_id=node.get("winnerId"),
        display_score=node.get("displayScore"),
        vod_url=node.get("vodUrl") or None,
        state=node.get("state"),
        event=_event(node["event"]) if node.get("event") else None,
        sides=[_side(slot) for slot in node.get("slots") or []],
        games=games,
    )


def _page_info(node: dict[str, Any] | None) -> PageInfo:
    node = node or {}
    return PageInfo(
        total=node.get("total") or 0,
        total_pages=node.get("totalPages") or 0,
        page=node.get("page") or 1,
        per_page=node.get("perPage") or 0,
    )


def user_slug(profile: str) -> str:
    """A start.gg profile url or slug as the API's user slug

    'https://www.start.gg/user/abc123', 'user/abc123' and 'abc123' all give 'user/abc123'.
    """
    match = _USER_SLUG_RE.search(profile)
    return f"user/{match.group(1) if match else profile.strip('/')}"


def event_ref(event: int | str) -> dict[str, Any]:
    """An event id, slug or page url as the API's `id` / `slug` variables

    Accepts 123456, 'tournament/genesis-9/event/ultimate-singles', or that event's page url.
    Raises ValueError for anything else (eg a tournament url without an event part).
    """
    if isinstance(event, int) or event.isdigit():
        return {"id": int(event), "slug": None}
    match = _EVENT_SLUG_RE.search(event)
    if match is None:
        raise ValueError(f"not an event id, slug or url: {event!r} (expected 'tournament/<name>/event/<name>')")
    return {"id": None, "slug": match.group(1)}


async def player(player_id: int) -> Player:
    """A player by start.gg player id, eg 158026. Raises ValueError if there is none"""
    data = await client.gql(queries.PLAYER, {"id": player_id})
    if not data.get("player"):
        raise ValueError(f"no start.gg player with id {player_id}")
    return _player(data["player"])


async def user_player(profile: str) -> Player:
    """Player behind a start.gg profile (url or slug, see `user_slug`); ValueError if none"""
    slug = user_slug(profile)
    data = await client.gql(queries.USER_PLAYER, {"slug": slug})
    user = data.get("user") or {}
    if not user.get("player"):
        raise ValueError(f"no start.gg player for profile {slug!r}")
    return _player(user["player"], user.get("slug") or slug)


async def _videogame(videogame_id: int) -> dict[str, Any]:
    data = await client.gql(queries.VIDEOGAME, {"id": videogame_id})
    return data.get("videogame") or {}


def startgg_character(character_id: int, name: str) -> Character:
    """One start.gg character with our `char_group` and `char_icon` (None for 'Random')"""
    ours = _CHAR_ID_BY_SITE_NAME.get(name, name)
    group = char_group_by_name(ours)
    return Character(
        id=character_id,
        name=name,
        # the enum itself, so a pick that isn't one of ours can't slip through as text
        char_group=CharGroup(group) if group else None,
        char_icon=char_icon_by_name(ours),
    )


async def videogame_characters(videogame_id: int = ULTIMATE) -> dict[int, Character]:
    """A videogame's characters by start.gg character id, with `char_group` filled in"""
    game = await _videogame(videogame_id)
    return {c["id"]: startgg_character(c["id"], c["name"]) for c in game.get("characters") or []}


async def videogame_stages(videogame_id: int = ULTIMATE) -> list[Stage]:
    """A videogame's stages"""
    game = await _videogame(videogame_id)
    return [Stage(id=s["id"], name=s["name"]) for s in game.get("stages") or []]


async def player_sets_page(  # mirrors the query's arguments
    player_id: int,
    *,
    page: int = 1,
    per_page: int = PER_PAGE,
    opponent_id: int | None = None,
    has_vod: bool | None = None,
    online: bool | None = None,
    singles_only: bool = False,
    query: str = queries.PLAYER_SETS,
    characters: dict[int, Character] | None = None,
    http: httpx2.AsyncClient | None = None,
) -> SetsPage:
    """One page of a player's sets as start.gg returns them: newest first, any videogame

    Args:
        player_id: start.gg player id, eg 158026.
        page: 1-based page number.
        per_page: sets per page; too many fails with ComplexityError (1000 objects a request).
        opponent_id: only sets against this player id (head-to-head).
        has_vod: True for only sets with a VOD link. Ignored by start.gg together with
            `opponent_id` (its docs allow only event / tournament / state filters there).
        online: True / False for only online / offline events; None for both. Same caveat.
        singles_only: ask start.gg for 1v1 sets only (its `entrantSize` filter), so doubles
            don't use up the page. Same caveat.
        query: PLAYER_SETS (everything) or USAGE_SETS (just what usage reads, twice the sets
            per request); both take the same variables.
        characters: `videogame_characters()`, fetched once by a caller that reads many pages
            (player_sets does); fetched here when not given. One request either way.
        http: an AsyncClient to reuse across pages.
    """
    filters: dict[str, Any] = {}
    if opponent_id is None:
        if has_vod:
            filters["hasVod"] = True
        if online is not None:
            filters["isEventOnline"] = online
        if singles_only:
            filters["entrantSize"] = [1]
    variables = {
        "id": player_id,
        "page": page,
        "perPage": per_page,
        "opponentId": opponent_id,
        "filters": filters or None,
    }
    if characters is None:
        data, characters = await asyncio.gather(
            client.gql(query, variables, client=http),
            videogame_characters(),
        )
    else:
        data = await client.gql(query, variables, client=http)
    if not data.get("player"):
        raise ValueError(f"no start.gg player with id {player_id}")
    sets = data["player"].get("sets") or {}
    return SetsPage(
        page_info=_page_info(sets.get("pageInfo")),
        sets=[_set(node, characters) for node in sets.get("nodes") or []],
    )


async def player_sets(  # one keyword per way of narrowing the sets
    player_id: int,
    *,
    max_sets: int = 150,
    since: dt.datetime | None = None,
    opponent_id: int | None = None,
    has_vod: bool | None = None,
    online: bool | None = None,
    videogame_id: int | None = ULTIMATE,
    singles_only: bool = True,
    per_page: int = PER_PAGE,
    max_pages: int | None = None,
    query: str = queries.PLAYER_SETS,
    characters: dict[int, Character] | None = None,
) -> list[Set]:
    """A player's completed sets, newest first, paged until `max_sets` or `since`

    Rows are start.gg's own, results included; the only work here is paging and leaving out
    sets that aren't asked for (other games, doubles, unfinished). DQ sets are kept.

    Args:
        player_id: start.gg player id, eg 158026.
        max_sets: stop after this many sets (the speed cap; some players have thousands).
        since: stop at sets completed before this (timezone-aware) time.
        opponent_id: only sets against this player id.
        has_vod: True for only sets with a VOD link.
        online: True / False for only online / offline events; None for both.
        videogame_id: only this game's sets (filtered here, start.gg can't); None for all.
        singles_only: drop sets where a side has more than one player.
        per_page: sets per request; lowered automatically if start.gg says it's too many.
        max_pages: at most this many requests for sets, whatever `max_sets` / `since` say
            (eg 1 for one quick look at the newest sets); None for no limit.
        query: PLAYER_SETS (everything) or USAGE_SETS (just what usage reads).
        characters: start.gg's characters by id (eg ds.data.startgg.stored_characters()), so
            no request is spent on them; fetched once (videogame_characters) when not given.
    """

    def wanted(s: Set) -> bool:
        event = s.event
        return (
            s.completed_at is not None
            and s.state in {None, _SET_COMPLETED}
            and (videogame_id is None or event is None or event.videogame_id in {None, videogame_id})
            and (not singles_only or all(len(side.players) <= 1 for side in s.sides))
            and (not has_vod or bool(s.vod_url))
            and (online is None or event is None or event.online is None or event.online == online)
        )

    async def collect(http: httpx2.AsyncClient, size: int, characters: dict[int, Character]) -> list[Set]:
        async def fetch(page: int) -> SetsPage:
            return await player_sets_page(
                player_id,
                page=page,
                per_page=size,
                opponent_id=opponent_id,
                has_vod=has_vod,
                online=online,
                singles_only=singles_only,
                query=query,
                characters=characters,
                http=http,
            )

        pages = [await fetch(1)]
        # other games' sets are dropped after paging: allow extra pages, but not without end
        last_allowed = min(pages[0].page_info.total_pages, math.ceil(max_sets / size) * 3, max_pages or math.inf)
        kept: list[Set] = []
        page_no, past_cutoff = 1, False
        while True:
            for s in (s for page in pages for s in page.sets):
                if since is not None and s.completed_at is not None and s.completed_at < since:
                    past_cutoff = True
                    break
                if wanted(s):
                    kept.append(s)
            if past_cutoff or len(kept) >= max_sets or page_no >= last_allowed:
                return kept[:max_sets]
            batch = range(page_no + 1, min(page_no + client.MAX_PARALLEL, last_allowed) + 1)
            pages = list(await asyncio.gather(*(fetch(p) for p in batch)))
            page_no = batch[-1]

    # one log group for the whole lookup (joins the caller's, eg a tool's, when there is one)
    with log_group(f"player_sets:{player_id}"):
        # once per call, not per page: every page needs it, and nothing keeps it between calls
        if characters is None:
            characters = await videogame_characters()
        async with httpx2.AsyncClient(timeout=30) as http:
            retry = 0
            while True:
                try:
                    # restarts are marked in the log, so their pages don't look like repeats
                    with logger.contextualize(retry=retry) if retry else contextlib.nullcontext():
                        return await collect(http, per_page, characters)
                except client.ComplexityError as e:
                    # any page can be the one that is too big (long sets cost more). Page
                    # numbers depend on the page size, so start over with a smaller one.
                    smaller = int(per_page * client.MAX_OBJECTS_PER_REQUEST / (e.actual or 2000) * 0.9)
                    if per_page == 1:
                        raise
                    per_page = max(1, min(smaller, per_page - 1))
                    retry += 1


async def tournaments(  # one keyword per search filter
    *,
    country: str = "",
    state: str = "",
    after: dt.datetime | None = None,
    before: dt.datetime | None = None,
    online: bool | None = None,
    name: str = "",
    upcoming: bool | None = None,
    page: int = 1,
    per_page: int = 25,
    videogame_id: int = ULTIMATE,
) -> TournamentsPage:
    """Search tournaments that have an event for a videogame (Ultimate by default)

    Args:
        country: two-letter country code, eg 'US'.
        state: state / province code, eg 'MD' (use with `country`).
        after: only tournaments starting after this time.
        before: only tournaments starting before this time.
        online: True for tournaments with online events, False for without; None for both.
        name: text the tournament name must contain, eg 'Genesis'.
        upcoming: True for upcoming only (soonest first), False for past only; None for both.
        page: 1-based page number.
        per_page: tournaments per page.
        videogame_id: start.gg videogame id.
    """
    filter_: dict[str, Any] = {"videogameIds": [videogame_id]}
    optional = {
        "countryCode": country or None,
        "addrState": state or None,
        "afterDate": int(after.timestamp()) if after else None,
        "beforeDate": int(before.timestamp()) if before else None,
        "hasOnlineEvents": online,
        "name": name or None,
        "upcoming": True if upcoming else None,
        "past": True if upcoming is False else None,
    }
    filter_ |= {k: v for k, v in optional.items() if v is not None}
    variables = {
        "page": page,
        "perPage": per_page,
        "filter": filter_,
        "sortBy": "startAt asc" if upcoming else "startAt desc",
        "videogameIds": [videogame_id],
    }
    data = await client.gql(queries.TOURNAMENTS, variables)
    found = data.get("tournaments") or {}
    return TournamentsPage(
        page_info=_page_info(found.get("pageInfo")),
        tournaments=[_tournament(node) for node in found.get("nodes") or []],
    )


async def _event_page(query: str, event: int | str, page: int, per_page: int) -> dict[str, Any]:
    variables = event_ref(event) | {"page": page, "perPage": per_page}
    data = await client.gql(query, variables)
    if not data.get("event"):
        raise ValueError(f"no start.gg event for {event!r}")
    return data["event"]


async def event_entrants(event: int | str, *, page: int = 1, per_page: int = 100) -> EntrantsPage:
    """One page of an event's entrants, with seed and current placement

    Args:
        event: event id, slug ('tournament/<name>/event/<name>') or page url.
        page: 1-based page number.
        per_page: entrants per page.
    """
    node = await _event_page(queries.EVENT_ENTRANTS, event, page, per_page)
    entrants = node.get("entrants") or {}
    return EntrantsPage(
        event=_event(node),
        page_info=_page_info(entrants.get("pageInfo")),
        entrants=[_entrant(e) for e in entrants.get("nodes") or []],
    )


async def event_standings(event: int | str, *, page: int = 1, per_page: int = 100) -> EntrantsPage:
    """One page of an event's standings: entrants ordered by placement, best first

    Args:
        event: event id, slug ('tournament/<name>/event/<name>') or page url.
        page: 1-based page number.
        per_page: standings per page.
    """
    node = await _event_page(queries.EVENT_STANDINGS, event, page, per_page)
    standings = node.get("standings") or {}
    return EntrantsPage(
        event=_event(node),
        page_info=_page_info(standings.get("pageInfo")),
        entrants=[_entrant(s["entrant"], s.get("placement")) for s in standings.get("nodes") or [] if s.get("entrant")],
    )


async def my_tournaments(*, upcoming: bool = True, per_page: int = 25, videogame_id: int = ULTIMATE) -> TournamentsPage:
    """Tournaments the token's own user is registered for or organizing

    Args:
        upcoming: True for upcoming ones, False for past ones.
        per_page: how many to return.
        videogame_id: only tournaments with this game.
    """
    when = {"upcoming": True} if upcoming else {"past": True}
    variables = {
        "perPage": per_page,
        "filter": when | {"videogameId": [videogame_id]},
        "videogameIds": [videogame_id],
    }
    data = await client.gql(queries.CURRENT_USER_TOURNAMENTS, variables)
    found = (data.get("currentUser") or {}).get("tournaments") or {}
    return TournamentsPage(
        page_info=_page_info(found.get("pageInfo")),
        tournaments=[_tournament(node) for node in found.get("nodes") or []],
    )
